head.script:
scwin.screenId = "jldfil59400";

///////// 1. 변수 및 선언 영역 /////////

scwin.form = null;

// 화면 전환 파라미터(loadTp/returnVal) — 스크립트 적재 시점 평가(as-is 타이밍 유지). EL 미치환 토큰("${…}")은 빈 값으로 간주한다.
scwin.loadTp = $c.data.readValue("dma_pageContext", "loadTp", { ctx: true, soft: true, label: "loadTp" });
scwin.loadTp = String(scwin.loadTp == null ? '' : scwin.loadTp);
scwin.loadTp = scwin.loadTp.indexOf('$' + '{') >= 0 ? '' : scwin.loadTp;

scwin.returnVal = $c.data.readValue("dma_pageContext", "returnVal", { ctx: true, soft: true, label: "returnVal" });
scwin.returnVal = String(scwin.returnVal == null ? '' : scwin.returnVal);
scwin.returnVal = scwin.returnVal.indexOf('$' + '{') >= 0 ? '' : scwin.returnVal;

///////// 2. 초기화 영역 /////////

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 초기화 함수(init_*)를 데이터 의존성 순서로 순차 실행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam(); // 1) 파라미터 수신 (dma_pageContext 확보)
        scwin.init_rowCopy(); // 2) 페이징 요약 문구(__rb0) 표시 복사
        scwin.init_conds(); // 3) 책임자 ID 여부(repIdYn) 표시 조건 평가
        scwin.init_sessionFill(); // 4) 세션 사용자 토큰(${session.user.*}) 치환
        await scwin.init_pageBody(); // 5) searchForm 참조 확보 + 처리 결과(loadTp) 알림
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil59400.onpageload' });
    }
};

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_conds
 * @description 세션의 책임자 ID 여부(session.user.repIdYn)에 따라 안내 문구(if_repIdYn)·목록 영역(if_repIdYn_2)·신규작성 버튼 영역(if_repIdYn_3)의 표시 조건을 평가한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_conds();
 */
scwin.init_conds = function () {
    const readRepIdYn = function () {
        return $c.data.readSessionValue("repIdYn", "session.user.repIdYn");
    };
    const binds = [{
        id: "if_repIdYn",
        fn: function () { return (readRepIdYn() === 'Y'); }
    }, {
        id: "if_repIdYn_3",
        fn: function () { return (readRepIdYn() === 'N'); }
    }, {
        id: "if_repIdYn_2",
        fn: function () { return (readRepIdYn() !== 'Y'); }
    }];
    $c.util.evalConds(binds);
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_rowCopy
 * @description dma_page(total/currentPage/pageCount) 값으로 "전체 n건 [x/y Page]" 페이징 요약 문구를 만들어 __rb0 텍스트박스에 복사한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_rowCopy();
 */
scwin.init_rowCopy = function () {
    const readPage = function (key) {
        return String($c.data.readValue("dma_page", key, { silent: true }));
    };
    const rowCopies = [{
        childId: "__rb0",
        fn: function () {
            return "전체 " + readPage("total") + "건 [" + readPage("currentPage") + "/" + readPage("pageCount") + " Page] ";
        }
    }];
    $c.data.copyRows(rowCopies);
};

/**
 * @method
 * @name initPageIndex
 * @description 페이지 크기 변경 시 조회 페이지 인덱스(dma_viewDetailReq.pageIndex)를 1로 되돌린 뒤 목록을 재조회한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.initPageIndex();
 */
scwin.initPageIndex = async function () {
    $c.util.getComponent('dma_viewDetailReq').set('pageIndex', 1);
    await scwin.fn_Search();
};

/**
 * @method
 * @name init_pageBody
 * @description searchForm 참조를 확보하고, 화면 전환 파라미터(returnVal/loadTp)에 따라 오류 안내 또는 제출(5)·수정요청(6)·철회(7)·삭제(4) 처리 결과를 알린다.
 * @returns {void}
 * @hidden N
 * @example await scwin.init_pageBody();
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.searchForm || { elements: [] });
        if (scwin.returnVal === "N") {
            await $c.win.alert('처리 중 오류가 발생하였습니다. 시스템 관리자에게 문의하여 주세요.');
        } else {
            if (scwin.loadTp === "5") {
                await $c.win.alert('제출 처리되었습니다.');
            } else {
                if (scwin.loadTp === "6") {
                    await $c.win.alert('수정요청 처리되었습니다.');
                } else {
                    if (scwin.loadTp === "7") {
                        await $c.win.alert('철회 처리되었습니다.');
                    } else {
                        if (scwin.loadTp === "4") {
                            await $c.win.alert('삭제 처리되었습니다.');
                        }
                    }
                }
            }
        }
    } catch (_ex) {
        await $c.exception.handleError(_ex, { context: 'jldfil59400.onpageload' });
    }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)
/**
 * @method
 * @name init_sessionFill
 * @description 화면 텍스트 노드·입력값에 남은 ${session.user.usrId} 토큰을 세션 사용자 정보($c.session.getUserInfo)로 치환한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_sessionFill();
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v;
            try {
                v = $c.session.getUserInfo(names[i]);
            } catch (_e) {
                $c.exception.handleError(_e, { notify: 'none', context: 'jldfil59400' });
                v = undefined;
            }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            const renderRoot = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document);
            const scanRoot = renderRoot.body || renderRoot;
            const doc = scanRoot.ownerDocument || scanRoot;
            const walker = doc.createTreeWalker(scanRoot, NodeFilter.SHOW_TEXT);
            let n;
            while ((n = walker.nextNode())) {
                if (n.nodeValue.indexOf(token) >= 0) {
                    n.nodeValue = n.nodeValue.split(token).join(v);
                }
            }
            const ins = renderRoot.querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) {
                if (ins[j].value && ins[j].value.indexOf(token) >= 0) {
                    ins[j].value = ins[j].value.split(token).join(v);
                }
            }
        }
    }
    fill();
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData").
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function () {
    $c.data.recvParamData('dma_pageContext');
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name slc_pageSize_onchange
 * @description 페이지 크기 셀렉트 변경 — 페이지 인덱스를 1로 초기화하고 목록을 재조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (slc_pageSize ev:onchange 바인딩으로 자동 호출)
 */
scwin.slc_pageSize_onchange = async function (e) {
    try {
        await scwin.initPageIndex();
    } catch (_ex) {
        await $c.exception.handleError(_ex, { context: 'jldfil59400.slc_pageSize_onchange' });
    }
};

/**
 * @event
 * @name grd_pageList_oncellclick
 * @description 목록 셀 클릭 — 비고(__rowAct) 칸이면 처리상태에 따라 수정요청 팝업(33·36) 또는 제출 처리(30·35·37)를 수행하고, 그 외 칸이면 처리상태별 loadTp(작성중 계열 1, 그 외 8)로 상세 화면을 조회한다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 열 인덱스
 * @param {String} columnId 클릭한 열 id
 * @returns {void}
 * @hidden N
 * @example (grd_pageList ev:oncellclick 바인딩으로 자동 호출)
 */
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        const r = dl && dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        const listProcsStatCd = r["listProcsStatCd"];
        if (columnId === "__rowAct") {
            if (listProcsStatCd === '33' || listProcsStatCd === '36') {
                scwin.fn_AdjReqPop(r["bzProcsNo"], "210", "80");
                return;
            }
            if (listProcsStatCd === '30' || listProcsStatCd === '35' || listProcsStatCd === '37') {
                await scwin.fn_EditStatus(r["bzProcsNo"], "applSubmit", "제출");
                return;
            }
            return;
        }
        if (listProcsStatCd !== '30' && listProcsStatCd !== '37' && listProcsStatCd !== '35') {
            await scwin.viewDetail(r["bzProcsNo"], "8");
            return;
        }
        if (listProcsStatCd === '30') {
            await scwin.viewDetail(r["bzProcsNo"], "1");
            return;
        }
        if (listProcsStatCd === '35') {
            await scwin.viewDetail(r["bzProcsNo"], "1");
            return;
        }
        if (listProcsStatCd === '37') {
            await scwin.viewDetail(r["bzProcsNo"], "1");
            return;
        }
        await scwin.viewDetail(r["bzProcsNo"], "9");
        return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @event
 * @name btn_newWrite_onclick
 * @description [신규작성] 버튼 클릭 — 전문평가 신청 작성 화면(jldfil59410)으로 이동한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_newWrite ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_newWrite_onclick = function (e) {
    try {
        scwin.newWrite();
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldfil59400.btn_newWrite_onclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name tx_viewDetail
 * @description 전문평가 신청 상세 조회를 서버에 요청한다(dma_viewDetailReq → dlt_pageList). 응답 실패 시 서버 메시지를 알린다.
 * @returns {Object} executeDynamic 응답 객체(resObj, 예외 시 null)
 * @hidden N
 * @example const res = await scwin.tx_viewDetail();
 */
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/listInvstg/specyValuAppl.do",
        ref: "dma_viewDetailReq",
        target: "dlt_pageList=body",
        isProcessMsg: false
    };
    let res = null;
    try {
        res = await $c.sbm.executeDynamic(sbmOptions);
    } catch (_e) {
        await $c.exception.handleError(_e, { notify: 'none', context: "jldfil59400.tx_viewDetail" });
        return null;
    }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) {
            await $c.win.alert(res.responseJSON.message);
        }
        return res;
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Search
 * @description 전문평가 신청 목록 조회를 서버에 요청한다(dma_SearchReq → dlt_pageList). 응답 실패 시 서버 메시지를 알린다.
 * @returns {Object} executeDynamic 응답 객체(resObj, 예외 시 null)
 * @hidden N
 * @example const res = await scwin.tx_fn_Search();
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/listInvstg/specyValuAppl.do",
        ref: "dma_SearchReq",
        target: "dlt_pageList=body",
        isProcessMsg: false
    };
    let res = null;
    try {
        res = await $c.sbm.executeDynamic(sbmOptions);
    } catch (_e) {
        await $c.exception.handleError(_e, { notify: 'none', context: "jldfil59400.tx_fn_Search" });
        return null;
    }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) {
            await $c.win.alert(res.responseJSON.message);
        }
        return res;
    }
    return res;
};

/**
 * @method
 * @name tx_fn_EditStatus
 * @description 선택 건의 처리상태 변경(제출 등)을 서버에 요청한다(dma_EditStatusReq → dlt_pageList). 응답 실패 시 서버 메시지를 알린다.
 * @returns {Object} executeDynamic 응답 객체(resObj, 예외 시 null)
 * @hidden N
 * @example const res = await scwin.tx_fn_EditStatus();
 */
scwin.tx_fn_EditStatus = async function () {
    const sbmOptions = {
        id: "tx_fn_EditStatus",
        method: "post",
        action: "/listInvstg/specyValuAppl.do",
        ref: "dma_EditStatusReq",
        target: "dlt_pageList=body",
        isProcessMsg: false
    };
    let res = null;
    try {
        res = await $c.sbm.executeDynamic(sbmOptions);
    } catch (_e) {
        await $c.exception.handleError(_e, { notify: 'none', context: "jldfil59400.tx_fn_EditStatus" });
        return null;
    }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) {
            await $c.win.alert(res.responseJSON.message);
        }
        return res;
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @event
 * @name grd_pageList_fillAct
 * @description dlt_pageList 적재 시 각 행의 처리상태 코드에 따라 비고(__rowAct) 칸 표시값(33·36 → 수정요청, 30·35·37 → 제출, 그 외 → -)을 채운다.
 * @returns {void}
 * @hidden N
 * @example (dlt_pageList ev:ondataload 바인딩으로 자동 호출)
 */
scwin.grd_pageList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getTotalRow(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) {
                const listProcsStatCd = r["listProcsStatCd"];
                if (listProcsStatCd === '33' || listProcsStatCd === '36') {
                    v = "수정요청";
                } else if (listProcsStatCd === '30' || listProcsStatCd === '35' || listProcsStatCd === '37') {
                    v = "제출";
                }
            }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.fillAct' });
    }
};

/**
 * @method
 * @name viewDetail
 * @description 요청 전문(dma_viewDetailReq)에 업무처리번호·method(editForm)·loadTp 를 설정하고 상세 조회(tx_viewDetail)를 실행한다.
 * @param {String} bzProcsNo 업무처리번호
 * @param {String} strLoadTp 상세 화면 loadTp 구분값
 * @returns {void}
 * @hidden N
 * @example await scwin.viewDetail(bzProcsNo, "1");
 */
scwin.viewDetail = async function (bzProcsNo, strLoadTp) {
    const viewDetailReq = $c.util.getComponent('dma_viewDetailReq');
    viewDetailReq.set('bzProcsNo', bzProcsNo);
    scwin.form.action = '/listInvstg/specyValuAppl.do';
    viewDetailReq.set('method', 'editForm');
    viewDetailReq.set('loadTp', strLoadTp);
    await scwin.tx_viewDetail();
};

/**
 * @method
 * @name newWrite
 * @description 전문평가 신청 작성 화면(jldfil59410)으로 페이지 프레임을 전환한다.
 * @returns {void}
 * @hidden N
 * @example scwin.newWrite();
 */
scwin.newWrite = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil59410/jldfil59410.xml');
};

/**
 * @method
 * @name fn_Search
 * @description searchForm action 을 설정하고 전문평가 신청 목록 조회(tx_fn_Search)를 실행한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_Search();
 */
scwin.fn_Search = async function () {
    scwin.form.action = "/listInvstg/specyValuAppl.do";
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name fn_EditStatus
 * @description 요청 전문(dma_viewDetailReq)에 method·업무처리번호를 설정하고, 확인 창 승인 시 처리상태 변경(tx_fn_EditStatus)을 실행한다.
 * @param {String} bzProcsNo 업무처리번호
 * @param {String} strMethod 서버 처리 method 명(예: applSubmit)
 * @param {String} strMsg 확인 창에 표시할 처리명(예: 제출)
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_EditStatus(bzProcsNo, "applSubmit", "제출");
 */
scwin.fn_EditStatus = async function (bzProcsNo, strMethod, strMsg) {
    scwin.form.action = "/listInvstg/specyValuAppl.do";
    const viewDetailReq = $c.util.getComponent('dma_viewDetailReq');
    viewDetailReq.set('method', strMethod);
    viewDetailReq.set('bzProcsNo', bzProcsNo);
    if (await $c.win.confirm(strMsg + '하시겠습니까?')) {
        await scwin.tx_fn_EditStatus();
    }
};

/**
 * @method
 * @name fn_AdjReqPop
 * @description 수정요청 가능 항목 선택 팝업(jldfil59410, selectAvailableAdjReq)을 500x250 팝업으로 연다.
 * @param {String} bzProcsNo 업무처리번호
 * @param {String} listInvstgBzTpCd 상장심사 업무 구분 코드
 * @param {String} listBzDtlTpCd 상장 업무 상세 구분 코드
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_AdjReqPop(bzProcsNo, "210", "80");
 */
scwin.fn_AdjReqPop = async function (bzProcsNo, listInvstgBzTpCd, listBzDtlTpCd) {
    const w = '500';
    const h = '250';
    const l = screen.width / 2 - w / 2;
    const t = screen.height / 2 - h / 2;
    const corpSearchURL = '/jldfil59410/jldfil59410.xml';
    await $c.win.openPopup(corpSearchURL, {
        id: "AdjReqPop",
        scrollbars: false,
        resizable: false,
        width: "500",
        height: "250",
        type: "pageFramePopup"
    }, {
        method: "selectAvailableAdjReq",
        bzProcsNo: bzProcsNo,
        listInvstgBzTpCd: listInvstgBzTpCd,
        listBzDtlTpCd: listBzDtlTpCd
    });
};

/**
 * @event
 * @name krxpage_pagenavigator_82_onclick
 * @description 페이지 내비게이터 클릭 — 선택한 페이지 인덱스를 요청 전문에 설정하고 목록을 재조회한다.
 * @param {Number} index 선택한 페이지 번호
 * @returns {void}
 * @hidden N
 * @example (krxpage_pagenavigator_82 ev:onclick 바인딩으로 자동 호출)
 */
scwin.krxpage_pagenavigator_82_onclick = function (index) {
    try {
        $c.util.getComponent('dma_viewDetailReq').set('pageIndex', index);
    } catch (e) {
        $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_82.page' });
    }
    scwin.fn_Search();
};
